async def act(page):
    """
    Create a new Shopping Cart Price Rule for a site-wide 20% Spring Sale for all customers.

    Strategy / plan:
    - Use a relative goto to the Shopping Cart Price Rule "new" page where the Add New Rule form usually lives.
    - Use accessibility-centered selectors (page.get_by_role(...)) for all interactions (fills, selects, checks, clicks).
    - Be defensive with try/except and attempt a few likely label names for form controls used in Magento 1 admin (e.g. "Rule Name", "Description", "Status", "Websites", "Customer Groups", "Coupon", "Apply", "Discount Amount").
    - Make the final action the Save button click (it may navigate away).

    Notes about the knowledge base functions:
    - There are no auxiliary functions available in the provided knowledge base for this task, so none were used.
    """
    # Navigate directly to the Add New Shopping Cart Price Rule page
    await page.goto("/index.php/admin/promo_quote/new/")
    await page.wait_for_load_state("networkidle")

    # Fill in Rule Name (try a couple of likely accessible names)
    try:
        await page.get_by_role("textbox", name="Rule Name").fill("Spring Sale - 20% Sitewide")
    except Exception:
        try:
            await page.get_by_role("textbox", name="Name").fill("Spring Sale - 20% Sitewide")
        except Exception:
            pass

    # Fill Description (textarea usually exposed as a textbox with label Description)
    try:
        await page.get_by_role("textbox", name="Description").fill("Spring Sale: 20% off site-wide for all customers")
    except Exception:
        # Some installs might label it differently; ignore if not found
        pass

    # Set Status to Enabled/Active (many Magento selects use value '1' for Enabled)
    try:
        await page.get_by_role("combobox", name="Status").select_option(value="1")
    except Exception:
        try:
            await page.get_by_role("combobox", name="Is Active").select_option(value="1")
        except Exception:
            pass

    # Select all Websites (try to find a group labelled 'Websites' and check all checkboxes under it)
    try:
        websites_group = page.get_by_role("group", name="Websites")
        website_checkboxes = websites_group.get_by_role("checkbox")
        wcount = await website_checkboxes.count()
        for i in range(wcount):
            cb = website_checkboxes.nth(i)
            if not await cb.is_checked():
                await cb.check()
    except Exception:
        # Fallback: try to check all checkboxes on the page (if specific grouping not found)
        try:
            all_cbs = page.get_by_role("checkbox")
            acount = await all_cbs.count()
            for i in range(acount):
                cb = all_cbs.nth(i)
                if not await cb.is_checked():
                    await cb.check()
        except Exception:
            pass

    # Select all Customer Groups
    try:
        cg_group = page.get_by_role("group", name="Customer Groups")
        cg_checkboxes = cg_group.get_by_role("checkbox")
        ccount = await cg_checkboxes.count()
        for i in range(ccount):
            cb = cg_checkboxes.nth(i)
            if not await cb.is_checked():
                await cb.check()
    except Exception:
        # If not found, ignore (many installs still will default to the common groups)
        pass

    # Set Coupon to 'No Coupon' (commonly value '1')
    try:
        await page.get_by_role("combobox", name="Coupon").select_option(value="1")
    except Exception:
        try:
            await page.get_by_role("combobox", name="Coupon Type").select_option(value="1")
        except Exception:
            pass

    # Set Sort Order / Priority to 0 (so it has normal precedence)
    try:
        await page.get_by_role("textbox", name="Priority").fill("0")
    except Exception:
        try:
            await page.get_by_role("textbox", name="Sort Order").fill("0")
        except Exception:
            pass

    # Actions: set Apply to percent discount and Discount Amount to 20
    try:
        # Prefer to access the Actions group if available
        actions_group = page.get_by_role("group", name="Actions")
        try:
            await actions_group.get_by_role("combobox", name="Apply").select_option(value="by_percent")
        except Exception:
            # fallback to a top-level combobox named Apply
            await page.get_by_role("combobox", name="Apply").select_option(value="by_percent")
    except Exception:
        # Top-level fallback
        try:
            await page.get_by_role("combobox", name="Apply").select_option(value="by_percent")
        except Exception:
            try:
                # Try selecting by visible label if value isn't known
                await page.get_by_role("combobox", name="Apply").select_option(label="Percent of product price discount")
            except Exception:
                pass

    # Discount Amount
    try:
        await page.get_by_role("textbox", name="Discount Amount").fill("20")
    except Exception:
        try:
            await page.get_by_role("textbox", name="Discount").fill("20")
        except Exception:
            pass

    # Small pause to ensure UI settled
    await page.wait_for_timeout(500)

    # Save the rule (final action; may navigate away)
    try:
        await page.get_by_role("button", name="Save").click()
        await page.wait_for_load_state("networkidle")
    except Exception:
        try:
            await page.get_by_role("button", name="Save Rule").click()
            await page.wait_for_load_state("networkidle")
        except Exception:
            # If Save button can't be found or clicked, raise to make the failure visible
            raise

